static gnrc_pktsnip_t *_create_snip(gnrc_pktsnip_t *next, const void *data, size_t size, /* <=== _create_snip */ 
                                    gnrc_nettype_t type)
{
    gnrc_pktsnip_t *pkt = _malloc(sizeof(gnrc_pktsnip_t));
    void *_data = NULL;

    if (pkt == NULL) {
        DEBUG("pktbuf: error allocating new packet snip\n");
        return NULL;
    }
    if (size > 0) {
        _data = _malloc(size);
        if (_data == NULL) {
            DEBUG("pktbuf: error allocating data for new packet snip\n");
            _free(pkt);
            return NULL;
        }
    }
    _set_pktsnip(pkt, next, _data, size, type);
    if (data != NULL) {
        memcpy(_data, data, size);
    }
    return pkt;
}

void gnrc_pktbuf_release_error(gnrc_pktsnip_t *pkt, uint32_t err) /* <=== gnrc_pktbuf_release_error */ 
{
    mutex_lock(&gnrc_pktbuf_mutex);
    while (pkt) {
        gnrc_pktsnip_t *tmp;
        assert(gnrc_pktbuf_contains(pkt));
        assert(pkt->users > 0);
        tmp = pkt->next;
        if (pkt->users == 1) {
            pkt->users = 0; /* not necessary but to be on the safe side */
            if (!IS_USED(MODULE_GNRC_TX_SYNC)
                || (pkt->type != GNRC_NETTYPE_TX_SYNC)) {
                gnrc_pktbuf_free_internal(pkt->data, pkt->size);
            }
            else {
                gnrc_tx_complete(pkt);
            }
            gnrc_pktbuf_free_internal(pkt, sizeof(gnrc_pktsnip_t));
        }
        else {
            pkt->users--;
        }
        DEBUG("pktbuf: report status code %" PRIu32 "\n", err);
        gnrc_neterr_report(pkt, err);
        pkt = tmp;
    }
    mutex_unlock(&gnrc_pktbuf_mutex);
}

