static bool _rbuf_update_ints(gnrc_sixlowpan_frag_rb_base_t *entry, /* <=== _rbuf_update_ints */ 
                              uint16_t offset, size_t frag_size)
{
    gnrc_sixlowpan_frag_rb_int_t *new;
    uint16_t end = (uint16_t)(offset + frag_size - 1);

    new = _rbuf_int_get_free();

    if (new == NULL) {
        DEBUG("6lo rfrag: no space left in rbuf interval buffer.\n");
        return false;
    }

    new->start = offset;
    new->end = end;

    DEBUG("6lo rfrag: add interval (%" PRIu16 ", %" PRIu16 ") to entry (%s, ",
          new->start, new->end, gnrc_netif_addr_to_str(entry->src,
                                                       entry->src_len,
                                                       l2addr_str));
    DEBUG("%s, %u, %u)\n", gnrc_netif_addr_to_str(entry->dst,
                                                  entry->dst_len,
                                                  l2addr_str),
          entry->datagram_size, entry->tag);

    LL_PREPEND(entry->ints, new);

    return true;
}

static int _rbuf_resize_for_reassembly(gnrc_sixlowpan_frag_rb_t *rbuf) /* <=== _rbuf_resize_for_reassembly */ 
{
    DEBUG("6lo rbuf: just do normal reassembly\n");
    if (gnrc_pktbuf_realloc_data(rbuf->pkt,
